CREATE OR REPLACE FUNCTION orbita_mobile_private.dispatch_snapshot(p_uid uuid, p_role text, p_outcome text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_order public.orbita_orders; v_offer orbita_mobile_private.dispatch_offers; v_online boolean:=false;
begin
  if p_role='passenger' then
    select * into v_order from public.orbita_orders where passenger_id=p_uid
      order by (status not in ('cancelled','completed')) desc,created_at desc,id desc limit 1;
  else
    select online into v_online from orbita_mobile_private.dispatch_drivers where driver_id=p_uid;
    select * into v_offer from orbita_mobile_private.dispatch_offers where driver_id=p_uid and status='pending';
    select * into v_order from public.orbita_orders
      where driver_id=p_uid or id=v_offer.order_id
      order by (status not in ('cancelled','completed')) desc,created_at desc,id desc limit 1;
  end if;
  return jsonb_build_object('contract_version',2,'server_time',clock_timestamp(),'user_id',p_uid,
    'role',p_role,'outcome',p_outcome,'online',coalesce(v_online,false),
    'order',case when v_order.id is null then null else to_jsonb(v_order) end,
    'offer',case when v_offer.id is null then null else jsonb_build_object(
      'id',v_offer.id,'order_id',v_offer.order_id,'expires_at',v_offer.expires_at) end);
end $function$

CREATE OR REPLACE FUNCTION orbita_mobile_private.order_point(p_point jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_address text;
  v_latitude numeric;
  v_longitude numeric;
begin
  if p_point is null or pg_catalog.jsonb_typeof(p_point)<>'object' then
    raise exception using errcode='P0001', message='ORB_ORDER_INVALID_REQUEST';
  end if;
  if (select count(*) from pg_catalog.jsonb_object_keys(p_point))<>3
     or not (p_point ?& array['address','latitude','longitude'])
     or pg_catalog.jsonb_typeof(p_point->'address')<>'string'
     or pg_catalog.jsonb_typeof(p_point->'latitude')<>'number'
     or pg_catalog.jsonb_typeof(p_point->'longitude')<>'number' then
    raise exception using errcode='P0001', message='ORB_ORDER_INVALID_REQUEST';
  end if;
  v_address:=pg_catalog.btrim(pg_catalog.regexp_replace((p_point->>'address') collate "C",
    E'[\u0009-\u000D\u0020\u0085\u00A0\u1680\u2000-\u200A\u2028\u2029\u202F\u205F\u3000\uFEFF]+',
    ' ','g'),' ');
  v_latitude:=(p_point->>'latitude')::numeric;
  v_longitude:=(p_point->>'longitude')::numeric;
  if pg_catalog.char_length(v_address) not between 1 and 500
     or v_latitude not between -90 and 90
     or v_longitude not between -180 and 180 then
    raise exception using errcode='P0001', message='ORB_ORDER_INVALID_REQUEST';
  end if;
  return pg_catalog.jsonb_build_object(
    'address',v_address,'latitude',v_latitude,'longitude',v_longitude);
end;
$function$

CREATE OR REPLACE FUNCTION orbita_mobile_private.order_session_uid()
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid;
  v_claim_uid uuid;
  v_session uuid;
  v_claims jsonb;
  v_exp numeric;
  v_now timestamptz:=pg_catalog.clock_timestamp();
begin
  begin
    v_uid:=auth.uid();
    v_claims:=auth.jwt();
    if v_uid is null or pg_catalog.jsonb_typeof(v_claims->'exp') is distinct from 'number'
       or pg_catalog.jsonb_typeof(v_claims->'sub') is distinct from 'string'
       or pg_catalog.jsonb_typeof(v_claims->'session_id') is distinct from 'string' then
      raise exception using errcode='28000', message='ORB_ORDER_SESSION_REQUIRED';
    end if;
    v_session:=(v_claims->>'session_id')::uuid;
    v_claim_uid:=(v_claims->>'sub')::uuid;
    v_exp:=(v_claims->>'exp')::numeric;
  exception when invalid_text_representation or numeric_value_out_of_range then
    raise exception using errcode='28000', message='ORB_ORDER_SESSION_REQUIRED';
  end;
  if v_claim_uid is distinct from v_uid or v_exp<=extract(epoch from v_now) or not exists (
    select 1 from auth.sessions s join auth.users u on u.id=s.user_id
    where s.id=v_session and s.user_id=v_uid and (s.not_after is null or s.not_after>v_now)
  ) then
    raise exception using errcode='28000', message='ORB_ORDER_SESSION_REQUIRED';
  end if;
  return v_uid;
end;
$function$

CREATE OR REPLACE FUNCTION public.orbita_cancel_order(p_order_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid;
  v_order public.orbita_orders;
  v_now timestamptz;
begin
  perform orbita_mobile_private.lock_access();
  v_uid:=orbita_mobile_private.order_session_uid();
  if p_order_id is null then
    raise exception using errcode='P0001', message='ORB_ORDER_INVALID_REQUEST';
  end if;
  select * into v_order from public.orbita_orders where id=p_order_id and passenger_id=v_uid;
  if not found then
    raise exception using errcode='P0001', message='ORB_ORDER_NOT_FOUND';
  end if;
  v_now:=pg_catalog.clock_timestamp();
  if v_order.status='cancelled' then
    return orbita_mobile_private.order_envelope(v_order,v_now);
  elsif v_order.status<>'created' then
    raise exception using errcode='P0001', message='ORB_ORDER_STATE_CHANGED';
  end if;
  update public.orbita_orders set status='cancelled',version=2,
    cancellation_reason=case when expires_at<=v_now then 'search_timeout' else 'passenger' end,
    cancelled_at=case when expires_at<=v_now then expires_at else v_now end
    where id=v_order.id and passenger_id=v_uid and status='created'
    returning * into v_order;
  if not found then
    raise exception using errcode='P0001', message='ORB_ORDER_STATE_CHANGED';
  end if;
  return orbita_mobile_private.order_envelope(v_order,v_now);
end;
$function$

CREATE OR REPLACE FUNCTION public.orbita_create_order(p_request_id uuid, p_pickup jsonb, p_destination jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid;
  v_pickup jsonb;
  v_destination jsonb;
  v_order public.orbita_orders;
  v_now timestamptz;
begin
  -- Тот же mutex, что у блокировки/смены роли. Проверки идут ПОСЛЕ ожидания.
  perform orbita_mobile_private.lock_access();
  v_uid:=orbita_mobile_private.order_session_uid();
  if p_request_id is null then
    raise exception using errcode='P0001', message='ORB_ORDER_INVALID_REQUEST';
  end if;
  v_pickup:=orbita_mobile_private.order_point(p_pickup);
  v_destination:=orbita_mobile_private.order_point(p_destination);
  if v_pickup->'latitude'=v_destination->'latitude'
     and v_pickup->'longitude'=v_destination->'longitude' then
    raise exception using errcode='P0001', message='ORB_ORDER_INVALID_REQUEST';
  end if;
  select * into v_order from public.orbita_orders
    where passenger_id=v_uid and request_id=p_request_id;
  if found then
    if v_order.pickup<>v_pickup or v_order.destination<>v_destination then
      raise exception using errcode='P0001', message='ORB_ORDER_IDEMPOTENCY_CONFLICT';
    end if;
    return orbita_mobile_private.order_envelope(v_order,pg_catalog.clock_timestamp());
  end if;
  -- Чтение/replay/отмена своих доступны после отзыва роли; НОВОЕ создание нет.
  if not exists (
    select 1 from public.orbita_profiles p
    join public.orbita_account_access a using(user_id)
    join public.orbita_user_roles r using(user_id)
    where p.user_id=v_uid and not a.is_blocked and r.role='passenger'
  ) then
    raise exception using errcode='42501', message='ORB_ORDER_CREATE_FORBIDDEN';
  end if;
  v_now:=pg_catalog.clock_timestamp();
  update public.orbita_orders set status='cancelled',cancellation_reason='search_timeout',
    cancelled_at=expires_at,version=2
    where passenger_id=v_uid and status='created' and expires_at<=v_now;
  if exists (select 1 from public.orbita_orders where passenger_id=v_uid and status='created') then
    raise exception using errcode='P0001', message='ORB_ORDER_ACTIVE_EXISTS';
  end if;
  v_now:=pg_catalog.clock_timestamp();
  insert into public.orbita_orders(passenger_id,request_id,pickup,destination,created_at,expires_at)
    values(v_uid,p_request_id,v_pickup,v_destination,v_now,v_now+interval '5 minutes')
    returning * into v_order;
  return orbita_mobile_private.order_envelope(v_order,v_now);
end;
$function$

CREATE OR REPLACE FUNCTION public.orbita_dispatch(p_action text, p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid; v_role text; v_now timestamptz; v_order public.orbita_orders;
  v_offer orbita_mobile_private.dispatch_offers; v_online boolean; v_outcome text:='ok'; v_next text; v_ack uuid;
begin
  perform orbita_mobile_private.lock_access();
  v_uid:=orbita_mobile_private.order_session_uid();
  if p_action is null or p_payload is null or jsonb_typeof(p_payload)<>'object' then
    raise exception 'ORB_DISPATCH_INVALID';
  end if;
  if p_action in ('passenger_poll','create','cancel') then v_role:='passenger';
  elsif p_action in ('driver_poll','online','respond','advance') then v_role:='driver';
  else raise exception 'ORB_DISPATCH_INVALID'; end if;
  if not orbita_mobile_private.dispatch_allowed(v_uid,v_role) then
    raise exception using errcode='42501',message='ORB_DISPATCH_FORBIDDEN';
  end if;
  -- Expire old leases BEFORE heartbeat; reopening cannot silently go online.
  perform orbita_mobile_private.dispatch_tick();
  v_now:=clock_timestamp();
  if v_role='driver' then
    insert into orbita_mobile_private.dispatch_drivers(driver_id,heartbeat_at) values(v_uid,v_now)
      on conflict(driver_id) do update set heartbeat_at=excluded.heartbeat_at;
  end if;
  if p_action='create' then
    -- v1 retains canonical validation and persistent request-ID replay.
    if exists(select 1 from public.orbita_orders where passenger_id=v_uid
      and status not in ('created','cancelled','completed')
      and request_id is distinct from (p_payload->>'request_id')::uuid) then
      raise exception 'ORB_ORDER_ACTIVE_EXISTS';
    end if;
    perform public.orbita_create_order((p_payload->>'request_id')::uuid,p_payload->'pickup',p_payload->'destination');
    v_ack:=(p_payload->>'request_id')::uuid;
  elsif p_action='cancel' then
    perform public.orbita_cancel_order((p_payload->>'order_id')::uuid);
  elsif p_action='online' then
    if jsonb_typeof(p_payload->'online') is distinct from 'boolean' then raise exception 'ORB_DISPATCH_INVALID'; end if;
    v_online:=(p_payload->>'online')::boolean;
    update orbita_mobile_private.dispatch_drivers set online=v_online,
      queue_position=case when v_online and not online then nextval('orbita_mobile_private.dispatch_queue') else queue_position end
      where driver_id=v_uid;
  elsif p_action='respond' then
    if (p_payload->>'response') is null or (p_payload->>'response') not in ('accept','decline') then
      raise exception 'ORB_DISPATCH_INVALID';
    end if;
    select * into v_offer from orbita_mobile_private.dispatch_offers
      where id=(p_payload->>'offer_id')::uuid and driver_id=v_uid;
    if not found then raise exception 'ORB_DISPATCH_NOT_FOUND'; end if;
    if v_offer.status<>'pending' then v_outcome:='already_processed';
    elsif v_offer.expires_at<=clock_timestamp() then v_outcome:='stale_offer';
    else
      select * into v_order from public.orbita_orders where id=v_offer.order_id;
      if v_order.status<>'created' or v_order.expires_at<=clock_timestamp() then v_outcome:='stale_offer';
      else
        update orbita_mobile_private.dispatch_offers set status=case when p_payload->>'response'='accept' then 'accepted' else 'declined' end
          where id=v_offer.id;
        update orbita_mobile_private.dispatch_drivers set queue_position=nextval('orbita_mobile_private.dispatch_queue') where driver_id=v_uid;
        if p_payload->>'response'='accept' then
          update public.orbita_orders set driver_id=v_uid,status='accepted',version=version+1 where id=v_order.id;
        end if;
      end if;
    end if;
  elsif p_action='advance' then
    select * into v_order from public.orbita_orders where id=(p_payload->>'order_id')::uuid and driver_id=v_uid;
    if not found then raise exception 'ORB_DISPATCH_NOT_FOUND'; end if;
    v_next:=p_payload->>'status';
    if v_next is null then raise exception 'ORB_DISPATCH_INVALID'; end if;
    if v_order.status=v_next then v_outcome:='already_processed';
    elsif (v_order.status='accepted' and v_next='to_pickup')
      or (v_order.status='to_pickup' and v_next='arrived')
      or (v_order.status='arrived' and v_next='riding')
      or (v_order.status='riding' and v_next='completed') then
      update public.orbita_orders set status=v_next,version=version+1,
        completed_at=case when v_next='completed' then clock_timestamp() else null end where id=v_order.id;
    else raise exception 'ORB_ORDER_STATE_CHANGED'; end if;
  end if;
  perform orbita_mobile_private.dispatch_tick();
  return orbita_mobile_private.dispatch_snapshot(v_uid,v_role,v_outcome)
    || jsonb_build_object('acknowledged_request_id',v_ack);
end $function$

CREATE OR REPLACE FUNCTION public.orbita_get_current_order()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid:=orbita_mobile_private.order_session_uid();
  v_order public.orbita_orders;
  v_now timestamptz:=pg_catalog.clock_timestamp();
begin
  -- Активный предпочитается даже при равных временах; затем последний receipt.
  select * into v_order from public.orbita_orders
    where passenger_id=v_uid and status='created' and expires_at>v_now;
  if not found then
    select * into v_order from public.orbita_orders where passenger_id=v_uid
      order by created_at desc,id desc limit 1;
  end if;
  return orbita_mobile_private.order_envelope(v_order,pg_catalog.clock_timestamp());
end;
$function$

CREATE OR REPLACE FUNCTION public.orbita_get_order(p_order_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid:=orbita_mobile_private.order_session_uid();
  v_order public.orbita_orders;
begin
  if p_order_id is null then
    raise exception using errcode='P0001', message='ORB_ORDER_INVALID_REQUEST';
  end if;
  select * into v_order from public.orbita_orders where id=p_order_id and passenger_id=v_uid;
  if not found then
    raise exception using errcode='P0001', message='ORB_ORDER_NOT_FOUND';
  end if;
  return orbita_mobile_private.order_envelope(v_order,pg_catalog.clock_timestamp());
end;
$function$
